<dialog id="arc-report-period" class="arc-report-dialog" aria-labelledby="arc-report-period-title">
 <div class="arc-report-head"><div><small>ARCOLL / RELATÓRIOS</small><h2 id="arc-report-period-title">Emitir relatório da rede</h2></div><button type="button" class="arc-report-close" data-arc-close="arc-report-period" aria-label="Fechar">&times;</button></div>
 <div class="arc-report-body"><form id="arc-report-form"><div class="arc-report-form"><label>Tipo de relatório<select id="arc-report-type" required><option value="monitoramento">Monitoramento</option><option value="velocidade">Velocidade</option><option value="dispositivos">Dispositivos</option><option value="mapa">Mapa lógico da rede</option></select></label><label>Data inicial<input type="date" id="arc-report-from" required></label><label>Data final<input type="date" id="arc-report-to" required></label></div><p class="arc-report-hint">Período máximo de 366 dias. O relatório utiliza eventos efetivamente registrados pelo agente selecionado.</p><p id="arc-report-error" class="arc-report-error" role="alert" hidden></p><div class="arc-report-actions"><button type="button" class="asc-btn" data-arc-close="arc-report-period">Cancelar</button><button type="submit" class="asc-btn asc-primary" id="arc-report-generate"><i class="fa fa-file-text-o"></i> Gerar prévia A4</button></div></form></div>
</dialog>
<dialog id="arc-report-preview" class="arc-report-dialog arc-report-preview-dialog" aria-labelledby="arc-report-preview-title"><div class="arc-report-head"><div><small>VISUALIZAÇÃO / A4</small><h2 id="arc-report-preview-title">Prévia para impressão</h2></div><button type="button" class="arc-report-close" data-arc-close="arc-report-preview" aria-label="Fechar">&times;</button></div><div class="arc-report-body"><article class="arc-report-sheet" id="arc-report-sheet"></article></div><div class="arc-report-actions" style="padding:0 18px 14px"><button type="button" class="asc-btn" id="arc-report-back">Alterar período</button><button type="button" class="asc-btn asc-primary" id="arc-report-print"><i class="fa fa-print"></i> Imprimir</button></div></dialog>
<script>
(()=>{'use strict';
 const by=id=>document.getElementById(id),op=by('arc-report-open'),period=by('arc-report-period'),preview=by('arc-report-preview'),form=by('arc-report-form');if(!op||!period||!preview)return;
 const now=new Date(),today=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');const month=new Date(now);month.setDate(month.getDate()-29);const start=[month.getFullYear(),String(month.getMonth()+1).padStart(2,'0'),String(month.getDate()).padStart(2,'0')].join('-');by('arc-report-to').value=today;by('arc-report-from').value=start;by('arc-report-to').max=today;by('arc-report-from').max=today;
 const el=(tag,txt,cls)=>{const v=document.createElement(tag);v.textContent=String(txt??'—');if(cls)v.className=cls;return v};
 const format=v=>{const x=String(v||'');const d=new Date(x.replace(' ','T'));return Number.isNaN(d.getTime())?x:d.toLocaleString('pt-BR')};
 op.addEventListener('click',()=>period.showModal());document.querySelectorAll('[data-arc-close]').forEach(b=>b.addEventListener('click',()=>by(b.dataset.arcClose).close()));
 const error=msg=>{by('arc-report-error').hidden=!msg;by('arc-report-error').textContent=msg};
 form.addEventListener('submit',async e=>{e.preventDefault();error('');const from=by('arc-report-from').value,to=by('arc-report-to').value;if(!from||!to||from>to)return error('Informe um período válido.');const days=Math.round((Date.parse(to)-Date.parse(from))/86400000);if(days>365)return error('O intervalo não pode ultrapassar 366 dias.');const b=by('arc-report-generate');b.disabled=true;try{const query=new URLSearchParams({network:<?= (int)$networkId ?>,agent:<?= (int)$selectedAgentId ?>,from,to,report:by('arc-report-type').value});const res=await fetch(<?=json_encode(arc_workspace_base_url().'api/network-report.php')?>+'?'+query,{credentials:'same-origin',cache:'no-store'});const body=await res.text();let data;try{data=JSON.parse(body)}catch(_){throw new Error(res.status===404?'Serviço de relatórios não encontrado. Verifique a instalação dos arquivos.':res.status===401||res.status===403?'Sessão expirada ou acesso negado. Entre novamente na plataforma.':'O servidor não retornou JSON válido (HTTP '+res.status+'). Verifique o log PHP.')}if(!res.ok||!data.ok)throw new Error(data.error||'Falha ao gerar relatório');draw(data);period.close();preview.showModal()}catch(ex){error(ex.message||'Não foi possível consultar os dados')}finally{b.disabled=false}});
 const reportLabels={monitoramento:'MONITORAMENTO',velocidade:'VELOCIDADE',dispositivos:'DISPOSITIVOS',mapa:'MAPA LÓGICO'};
 function draw(data){const sheet=by('arc-report-sheet');sheet.replaceChildren();sheet.append(el('h1','ARCOLL / '+(reportLabels[data.report]||'RELATÓRIO')));
 const meta=el('div','','rmeta'),ident=el('div');ident.append(el('strong',data.network.name),el('div','Agente: '+data.agent,'rmuted'));meta.append(ident,el('div','Período: '+data.from+' a '+data.to+' · Emitido: '+new Date().toLocaleString('pt-BR'),'rmuted'));sheet.append(meta);
 const kpis=el('div','','rkpis');for(const [label,value] of [['Registros no período',data.total],['Categorias',data.types.length],['Última atividade',data.last_activity?format(data.last_activity):'Não disponível']]){const c=el('div');c.append(el('small',label),el('strong',value));kpis.append(c)}sheet.append(kpis);
 if(data.report==='mapa'||data.report==='dispositivos'){
  const devices=Array.isArray(data.devices)?data.devices:[];
  const label=el('h2',data.report==='mapa'?'MAPA LÓGICO DOS DISPOSITIVOS':'INVENTÁRIO DOS DISPOSITIVOS');sheet.append(label);
  sheet.append(el('p','Inventário atual da rede, consultado na emissão. Não representa necessariamente a situação histórica do período selecionado.','rmuted'));
  if(data.report==='mapa'&&devices.length){const canvas=el('div','','arc-report-netmap');const center=el('div','','arc-report-netcenter');center.append(el('i','⌘'),el('strong',data.network.name));canvas.append(center);const nodes=el('div','','arc-report-netnodes');for(const d of devices.slice(0,40)){const node=el('div','','arc-report-netnode');node.append(el('span',d.agent_installed?'▣':'◉'),el('strong',d.name),el('small',d.ip||'IP não disponível'));nodes.append(node)}canvas.append(nodes);sheet.append(canvas);if(devices.length>40)sheet.append(el('small','Mapa resumido aos primeiros 40 dispositivos.'))}
  const t=document.createElement('table'),h=document.createElement('tr');for(const v of ['Dispositivo','IP','MAC','Situação'])h.append(el('th',v));t.append(h);for(const d of devices.slice(0,65)){const tr=document.createElement('tr');for(const v of [d.name,d.ip,d.mac,d.status==='online'?'Online':'Offline'])tr.append(el('td',v||'—'));t.append(tr)}sheet.append(t);if(!devices.length)sheet.append(el('p','Nenhum dispositivo inventariado para este agente.'));}
 else {sheet.append(el('h2','RESUMO DOS DADOS REGISTRADOS'));if(!data.types.length)sheet.append(el('p','Nenhuma medição deste tipo foi recebida no período.'));else{const t=document.createElement('table'),h=document.createElement('tr');for(const x of ['Medição','Registros'])h.append(el('th',x));t.append(h);for(const x of data.types){const tr=document.createElement('tr');tr.append(el('td',x.type),el('td',x.count));t.append(tr)}sheet.append(t)}sheet.append(el('h2','ÚLTIMAS MEDIÇÕES'));if(!data.events.length)sheet.append(el('p','Nenhuma ocorrência encontrada.'));else{const t=document.createElement('table'),h=document.createElement('tr');for(const x of ['Data/hora','Medição','Agente'])h.append(el('th',x));t.append(h);for(const x of data.events){const tr=document.createElement('tr');tr.append(el('td',format(x.at)),el('td',x.type),el('td',x.machine));t.append(tr)}sheet.append(t)}}
 sheet.append(el('p','Fonte: registros armazenados na plataforma. Quando disponíveis, os dados são coletados pelo agente Windows. A listagem é limitada aos registros mais recentes; os totais consideram todo o período.','rfoot'));
 }
 by('arc-report-back').addEventListener('click',()=>{preview.close();period.showModal()});by('arc-report-print').addEventListener('click',()=>window.print());
})();
</script>
